mod dsu;
#[path="../setup/fast.rs"]mod fast;
#[path="../multi/algebra.rs"]mod algebra;
#[path="../normalized/source.rs"]mod source;
#[path="../orbit-core/sparse.rs"]mod sparse;
use hec_native_ic::{counted,fp::Fp,jac::Curve,poly::Poly,rng::Rng,solve::{solve_for_last,Row,SolveStats,Solver}};
use std::{collections::BTreeMap,fs};
struct Input{a:u64,support:Vec<(usize,u64,u64)>}
fn row(v:&[u64])->Row{v.iter().enumerate().filter_map(|(j,&x)|(x!=0).then_some((j as u32,x))).collect()}
fn main(){counted::disable();let mut input=BTreeMap::<(u64,u64),Vec<Input>>::new();for l in fs::read_to_string("research/hec_residual_span_20261116/incidence-oracle/ROOTS.tsv").unwrap().lines().skip(1){let v:Vec<_>=l.split('\t').collect();let n=|j:usize|v[j].parse::<u64>().unwrap();let support=v[5].split(',').map(|s|{let z:Vec<u64>=s.split(':').map(|x|x.parse().unwrap()).collect();assert_eq!(z.len(),3);(z[0]as usize,z[1],z[2])}).collect();input.entry((n(0),n(1))).or_default().push(Input{a:n(3),support});}
println!("p\tsm\tcore\tcolumns\tnormalized\tselected_rows\tfirst_rows\tfirst_anchor\tk\tfinal_rank");let(mut prefixes,mut completed,mut cores)=(0,0,0);
for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let(fb,z,a)=fast::prepare(&c);let(_,_,degree,lambda)=algebra::certificate(&a,ell);assert_eq!(degree,1);let lambda=lambda.unwrap();let f=Fp::new(ell);let mut map=vec![(usize::MAX,0);fb.len()];let mut cols=0;for j in 0..fb.len(){if map[j].0!=usize::MAX{continue}let(mut x,y,mut weight)=(fb[j].0,fb[j].1,1);for _ in 0..5{let q=fb.binary_search_by_key(&x,|p|p.0).unwrap();assert_eq!(map[q].0,usize::MAX);map[q]=(cols,if fb[q].1==y{weight}else{assert_eq!(fb[q].1,c.fp.neg(y));f.neg(weight)});x=c.fp.mul(x,z);weight=f.mul(weight,lambda);}assert_eq!(weight,1);cols+=1;}let base=c.place(fb[0].0,fb[0].1);let mut rng=Rng::new(2026112500^p);for sm in [1,17]{let d=c.mul(&base,sm);let qualification=1+rng.below(ell-1);let target=c.mul(&d,qualification);let normalization=source::equation(&c,&d,&fb,&map,cols,ell).map(|x|x.1);
for core in 0..1{cores+=1;let perm=|j:usize|if j==core{cols-1}else if j>core{j-1}else{j};let mut linear=sparse::Sparse::new(cols+1,ell);let mut affine=dsu::Affine::new(cols-1,ell);let mut sequence=vec![];let mut seen=vec![false;cols-1];let mut refs=vec![];if let Some(v)=&normalization{let mut w=vec![0;cols+1];for(j,&x)in v.iter().enumerate(){w[perm(j)]=x;}linear.insert(&w,1);affine.insert(&w,1);sequence.push((w.clone(),1));refs.push((row(&w),1));}
capture(&mut affine,&mut seen,&c,&d,&target,&base,&fb,&map,p,sm,0,0);let(mut selected,mut first)=(0,None);for item in &input[&(p,sm)]{if !item.support.iter().any(|x|x.0==core){continue}let mut coeff=vec![0;cols+1];for &(r,x,y)in &item.support{let j=fb.binary_search_by_key(&x,|p|p.0).unwrap();assert_eq!(r,map[j].0);let weight=if y==fb[j].1{map[j].1}else{assert_eq!(y,c.fp.neg(fb[j].1));f.neg(map[j].1)};let q=perm(r);coeff[q]=f.add(coeff[q],weight);}coeff[cols]=1;let rhs=f.neg(item.a%ell);linear.insert(&coeff,rhs);affine.insert(&coeff,rhs);assert_eq!(affine.rank(),linear.rank);assert_eq!(affine.k(),linear.k());sequence.push((coeff.clone(),rhs));refs.push((row(&coeff),rhs));selected+=1;capture(&mut affine,&mut seen,&c,&d,&target,&base,&fb,&map,p,sm,selected,item.a);let mut stats=SolveStats::default();let check=solve_for_last(&refs,cols,ell,Solver::Fast,&[],&mut stats);assert_eq!(check,linear.k());prefixes+=1;if let Some(k)=check{assert_eq!(c.mul(&d,k),target);if first.is_none(){first=Some((selected,item.a,k));}}}
if first.is_some(){completed+=1;}let(rr,aa,kk)=first.unwrap_or((0,0,0));println!("{p}\t{sm}\t{core}\t{cols}\t{}\t{selected}\t{rr}\t{aa}\t{}\t{}",normalization.is_some(),if first.is_some(){kk.to_string()}else{"none".into()},linear.rank);}}
}eprintln!("cores={cores} completed_cores={completed} checked_prefixes={prefixes} all_promotion_group_identities_and_reference_prefixes=true no_producer_rerun=true");}
fn capture(s:&mut dsu::Affine,seen:&mut[bool],c:&Curve,d:&hec_native_ic::jac::Div,t:&hec_native_ic::jac::Div,core:&hec_native_ic::jac::Div,fb:&[(u64,u64)],map:&[(usize,u64)],p:u64,sm:u64,row:usize,anchor:u64){
 for lp in 0..seen.len(){if seen[lp]{continue}let Some(h)=s.expression(lp)else{continue};seen[lp]=true;let j=map.iter().position(|v|v.0==lp+1&&v.1==1).unwrap();let point=c.place(fb[j].0,fb[j].1);let a=c.mul(core,h[0]);let b=c.mul(t,h[1]);let e=c.mul(d,h[2]);let result=c.add(&c.add(&a,&b),&e);assert_eq!(point,result);eprintln!("PROMOTE\t{p}\t{sm}\t{row}\t{anchor}\t{}\t{}\t{}\t{}\t{}",lp+1,h[0],h[1],h[2],s.k().is_some());
 }
}
